"""Shared fixtures: the running example log and its configuration."""

from pathlib import Path

import polars as pl
import pytest
from ocelescope import OCEL

from ocelescope_module_location_based_ocpm.derivation.config import (
    Activities,
    DerivationConfig,
    LocationAttribute,
    ObjectTypes,
)
from ocelescope_module_location_based_ocpm.derivation.pipeline import Derivation, derive

#: Folder of the running example (generated by data/running_example/make_running_example.py).
EXAMPLE = Path(__file__).parents[3] / "data" / "running_example"


@pytest.fixture(scope="session")
def ocel() -> OCEL:
    """The running example log."""
    return OCEL.read(EXAMPLE / "running_example.sqlite")


@pytest.fixture(scope="session")
def input_tables() -> dict[str, pl.DataFrame]:
    """The running example's inputs as tables, by file name."""
    return {path.stem: pl.read_csv(path) for path in (EXAMPLE / "inputs").glob("*.csv")}


def example_config(**changes) -> DerivationConfig:
    """The configuration that reproduces the running example of the concept.

    Args:
        **changes: Fields to replace, e.g. level=1.

    Returns:
        DerivationConfig: The configuration.
    """
    config = DerivationConfig(
        handling_units=ObjectTypes(object_types=["slab", "coil"]),
        movement_events=Activities(activities=["crane move", "load truck", "unload truck"]),
        transformation_events=Activities(activities=["cast slab", "roll", "cut"]),
        target_locations=LocationAttribute(attribute="to_loc"),
        pickup_locations=LocationAttribute(attribute="from_loc"),
    )
    return config.model_copy(update=changes)


@pytest.fixture(scope="session")
def derivation(ocel: OCEL) -> Derivation:
    """The derivation of the running example at Level 3."""
    return derive(ocel, example_config())


def expected(name: str) -> pl.DataFrame:
    """Read an expected-results table; empty cells are ⊥ (null).

    Args:
        name: File name without `.csv` in data/running_example/expected/.

    Returns:
        pl.DataFrame: The table, all columns as strings.
    """
    return pl.read_csv(EXAMPLE / "expected" / f"{name}.csv", infer_schema=False)
